function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= 1 && v <= 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(target) || target < 1 || target > 1e9) return 'target is an integer from 1 to 10^9.';
  for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  return null;
}

