function isMajorityElement(nums, target) {
  // Index of the first value that is at least value (nums.length if none is).
  const firstAtLeast = (value) => {
    let left = 0;
    let right = nums.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (nums[mid] < value) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    return left;
  };
  const start = firstAtLeast(target);
  const end = firstAtLeast(target + 1);
  const count = end - start;
  return count * 2 > nums.length;
}

