  const target = pick();
  // Aim the target's count near the half-way line, where off-by-one mistakes show.
  const half = Math.floor(n / 2);
  const roll = rand();
  let count = roll < 0.3 ? half : roll < 0.6 ? Math.min(n, half + 1) : roll < 0.8 ? Math.floor(rand() * (n + 1)) : 0;
  const nums = Array.from({ length: count }, () => target);
